const row = $json || {};
const status = String(row.status || '').trim();
const mission_key = String(row.mission_key || '').trim();
const mission_task_id = String(row.mission_task_id || '').trim();
if (status === 'assigned' && (!mission_key || !mission_task_id)) {
  return [{ json: { ...row, status: 'no_work', mission_key: null, mission_task_id: null, source: row.source || 'govhub-n8n', normalization_note: 'assigned_without_identity_downgraded_to_no_work' } }];
}
return [{ json: row }];
